CREATE OR REPLACE FUNCTION public.trip_core_finite_read_state_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare actor uuid;trip uuid;operation uuid;
begin
 trip:=(to_jsonb(coalesce(new,old))->>'trip_id')::uuid;
 if session_user='otr_trip_core_v2_gateway' or current_user='otr_trip_core_v2_writer' then
  actor:=nullif(current_setting('otr.core.actor',true),'')::uuid;
  if current_user<>'otr_trip_core_v2_writer' or session_user<>'otr_trip_core_v2_gateway' or tg_op not in ('INSERT','UPDATE') or not public.trip_core_finite_scope_allowed(actor,trip)
   or trip is distinct from nullif(current_setting('otr.core.trip',true),'')::uuid
   or (current_setting('otr.core.command',true) is distinct from 'CREATE_ITEM' and not (public.trip_sustained_dev_scope_allowed(actor,trip,null,'CORE') and (current_setting('otr.core.command',true) in ('SET_ITEM_TEXT','SET_ITEM_SCHEDULE','SET_ITEM_PLACE','SET_ITEM_PARTICIPATION') OR (current_setting('otr.core.command',true)='CREATE_SPARSE_FLIGHT' AND current_setting('otr.core.family',true)='P2' AND current_setting('otr.core.admission',true)='REVIEWED_SOURCE' AND EXISTS(SELECT 1 FROM public.trip_sustained_import_p1_capabilities(actor,trip) c WHERE c.runtime_enabled AND c.enabled_commands=ARRAY['CREATE_SPARSE_FLIGHT']::text[] AND c.enabled_families=ARRAY['P2']::text[]) AND current_setting('otr.core.operation',true)='50bfe576-c16d-8645-8cde-a355da5f13f9' AND current_setting('otr.core.target_item',true)='ec73e4fd-c580-8063-96a8-ef7accda3748' AND current_setting('otr.core.source_intent',true)='0886cd6b-02c1-8dc3-ba1e-29bc6543c6f4' AND EXISTS(SELECT 1 FROM public.trip_core_command_receipts rr JOIN public.trip_source_core_v2_slots ss ON ss.operation_id=rr.operation_id AND ss.intent_sha256=rr.intent_sha256 AND ss.account_id=rr.actor_account_id AND ss.trip_id=rr.trip_id WHERE rr.actor_account_id=actor AND rr.trip_id=trip AND rr.operation_id=nullif(current_setting('otr.core.operation',true),'')::uuid AND ss.output_slot_id=nullif(current_setting('otr.core.source_intent',true),'')::uuid AND ss.target_id=nullif(current_setting('otr.core.target_item',true),'')::uuid AND ss.command='CREATE_SPARSE_FLIGHT' AND rr.outcome IN ('APPLIED','NO_CHANGE') AND rr.body->>'command'='CREATE_SPARSE_FLIGHT')))))
   or tg_op='INSERT' and not exists(select 1 from public.trip_core_read_state where trip_id=trip)
   or tg_op='UPDATE' and (new.epoch is distinct from old.epoch or new.access_revision is distinct from old.access_revision or new.revision<>old.revision+1) then raise exception 'CORE_V2_CAPABILITY_CLOSED' using errcode='42501';end if;
 elsif session_user='otr_trip_create_gateway' then
  select r.actor_account_id,r.operation_id into actor,operation from public.trip_create_receipts r join public.trips t on t.id=r.trip_id and t.created_by=r.actor_account_id where r.trip_id=trip for share of r;
  if tg_op<>'INSERT' or not public.trip_create_finite_scope_allowed(actor,trip,operation) then raise exception 'TRIP_CREATE_CAPABILITY_CLOSED' using errcode='55000';end if;
 end if;
 -- Existing privileged membership invalidation retains its current authority.
 return coalesce(new,old);
end $function$

CREATE OR REPLACE FUNCTION public.trip_core_publication_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$ begin
 if tg_op<>'INSERT' then raise exception 'CORE_V2_PUBLICATION_IMMUTABLE' using errcode='42501';end if;
 if new.account_id is distinct from nullif(current_setting('otr.core.actor',true),'')::uuid or new.trip_id is distinct from nullif(current_setting('otr.core.trip',true),'')::uuid then raise exception 'CORE_SCOPE_MISMATCH' using errcode='42501';end if;
 if exists(select 1 from public.trip_source_runs rr where rr.id=new.run_id and rr.extractor_key='otr-universal-interpretation-v1') and not exists(select 1 from public.trip_sustained_import_p1_capabilities(new.account_id,new.trip_id) c where c.runtime_enabled and c.enabled_commands=ARRAY['CREATE_SPARSE_FLIGHT']::text[] and c.enabled_families=ARRAY['P2']::text[]) then raise exception 'P2_SOURCE_CAPABILITY_CLOSED' using errcode='42501';end if;
 if exists(select 1 from public.trip_source_runs rr where rr.id=new.run_id and rr.extractor_key='otr-universal-interpretation-v1') and
 (new.publication_id is distinct from '2d3ef30c-a3ee-81ba-8a8f-f6d2ecb4b57f'::uuid or new.request_json->'universalP2' is distinct from '{"batchId":"a9be165b-5a90-4244-add7-d4977c9e7ba5","proposedPlanSha256":"30ef32a53a14e3b80cb46b67a2ef8e451d134c55e6fd2950f5419d3511ce8d7f","resultSha256":"7300e350f5e93ec77b833a4f7d65c44b88fdee4208c7ed001d47375d7244bf94","runId":"8af82103-55f2-84ea-8e6f-445a15321cf6","sourceReview":{"decision":"NEW","departureDate":"2026-11-02","flightNumberLiteral":"NZ501","originalReviewed":true,"sourceRevision":1,"tripReviewed":true,"version":"otr.universal.p2-source-review/1"},"taskId":"7338329a-46eb-8050-9bec-96376f08b296","token":"i1","version":"otr.universal.p2-source-proposal/1"}'::jsonb
  or new.request_sha256 is distinct from '42bcceccf523049b73d8120d18e9374dbb889ec5cd0a4c60202b3b231854eb40' or public.trip_source_hash('otr-trip-core-source-publication-v2',new.request_json) is distinct from '42bcceccf523049b73d8120d18e9374dbb889ec5cd0a4c60202b3b231854eb40')
 then raise exception 'P2_UNIVERSAL_BINDING_REQUIRED' using errcode='23514';end if;
 if not exists(select 1 from public.trip_sources src join public.trip_source_runs r on r.id=new.run_id where src.id=new.source_id and src.trip_id=new.trip_id and src.acquired_by=new.account_id and src.current_material_revision=new.source_revision and src.lifecycle='ACTIVE' and src.retention_state='RETAINED' and r.trip_id=new.trip_id and r.actor_account_id=new.account_id and new.source_id=any(r.scope_source_ids) and (r.state='READY' or (r.state='PENDING' and r.extractor_key='otr-universal-interpretation-v1' and r.id='8af82103-55f2-84ea-8e6f-445a15321cf6'::uuid and r.capture_batch_id='a9be165b-5a90-4244-add7-d4977c9e7ba5'::uuid and r.interpretation_task_id='7338329a-46eb-8050-9bec-96376f08b296'::uuid and new.request_json->'universalP2'='{"batchId":"a9be165b-5a90-4244-add7-d4977c9e7ba5","proposedPlanSha256":"30ef32a53a14e3b80cb46b67a2ef8e451d134c55e6fd2950f5419d3511ce8d7f","resultSha256":"7300e350f5e93ec77b833a4f7d65c44b88fdee4208c7ed001d47375d7244bf94","runId":"8af82103-55f2-84ea-8e6f-445a15321cf6","sourceReview":{"decision":"NEW","departureDate":"2026-11-02","flightNumberLiteral":"NZ501","originalReviewed":true,"sourceRevision":1,"tripReviewed":true,"version":"otr.universal.p2-source-review/1"},"taskId":"7338329a-46eb-8050-9bec-96376f08b296","token":"i1","version":"otr.universal.p2-source-proposal/1"}'::jsonb)) and r.superseded_by is null and r.retention_state='RETAINED') then raise exception 'INPUT_STALE' using errcode='23514';end if;
 if tg_table_name='trip_source_core_v2_publications' then
  if not exists(select 1 from public.trip_source_runs where id=new.run_id and input_sha256=new.input_catalog_sha256) then raise exception 'INPUT_STALE' using errcode='23514';end if;
 else
  if not exists(select 1 from public.trip_source_core_v2_slots slot join public.trip_core_command_receipts receipt on receipt.id=new.domain_receipt_id where slot.output_slot_id=new.output_slot_id and slot.account_id=new.account_id and slot.trip_id=new.trip_id and slot.source_id=new.source_id and slot.candidate_id=new.candidate_id and slot.target_kind=new.target_kind and slot.target_id=new.target_id and slot.identity_sha256=new.identity_sha256 and receipt.actor_account_id=new.account_id and receipt.trip_id=new.trip_id and receipt.operation_id=slot.operation_id and receipt.intent_sha256=slot.intent_sha256 and receipt.receipt_sha256=new.receipt_sha256 and receipt.outcome in ('APPLIED','NO_CHANGE') and receipt.body->>'command'=slot.command and exists(select 1 from jsonb_array_elements(receipt.body->'targetVector') v where v->>'kind'=new.target_kind and v->>'id'=new.target_id::text and (v->>'committedRevision')::bigint=new.target_revision)) then raise exception 'RECEIPT_TARGET_MISMATCH' using errcode='23514';end if;
 end if;
 return new;
end $function$
